    "/health/live": {
      "get": {
        "operationId": "HealthController_liveness",
        "parameters": [],
        "responses": {
          "200": {
            "description": "Process is alive.",
            "content": {
              "application/json": {
                "schema": {
                  "example": {
                    "status": "alive"
                  }
                }
              }
            }
          }
        },
        "tags": [
          "health"
        ]
      }
    },
    "/health/ready": {
      "get": {
        "operationId": "HealthController_readiness",
        "parameters": [],
        "responses": {
          "200": {
            "description": "All dependencies are reachable.",
            "content": {
              "application/json": {
                "schema": {
                  "example": {
                    "status": "ready",
                    "checks": {
                      "postgres": "up",
                      "redis": "up",
                      "object_storage": "up"
                    }
                  }
                }
              }
            }
          },
          "503": {
            "description": "A dependency is unreachable or the process is shutting down."
          }
        },
        "tags": [
          "health"
        ]
      }
    },
