      "post": {
        "description": "Sets the HttpOnly session cookie and returns the CSRF token to send as `X-CSRF-Token` on every write. Five failed attempts per 15 minutes per address and username return 429.",
        "operationId": "AdminAuthController_logIn",
        "parameters": [],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "username": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 128
                  },
                  "password": {
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 1024
                  }
                },
                "required": [
                  "username",
                  "password"
                ]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": ""
          }
        },
        "security": [
          {
            "admin-session": []
          },
          {
            "admin-api-key": []
          }
        ],
        "summary": "Sign in",
        "tags": [
          "Admin: authentication"
