                          "type": "array",
                          "items": {
                            "type": "string",
                            "format": "uuid",
                            "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"
                          }
                        }
                      },
                      "required": [
                        "clientMessageId",
                        "content",
                        "attachmentIds"
                      ]
                    }
                  },
                  "replacesTurnId": {
                    "default": null,
                    "anyOf": [
                      {
                        "type": "string",
                        "format": "uuid",
                        "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"
                      },
                      {
                        "type": "null"
                      }
                    ]
                  }
                },
                "required": [
                  "turnId",
                  "messages"
                ]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "The turn's server-sent events, ending with `message.completed` or `error`"
          }
        },
        "security": [
          {
            "visitor-session": []
          }
        ],
        "summary": "Send a batch of visitor messages and stream the single reply",
        "tags": [
          "Public: turns"
        ]
      }
    },
    "/v1/public/conversations/{conversationId}/turns/{turnId}/events": {
      "get": {
        "description": "Sends events after `Last-Event-ID` (0 replays everything). Events are kept 10 minutes after the turn; 404 afterwards for unfinished turns.",
        "operationId": "PublicTurnsController_resume",
        "parameters": [
          {
            "name": "conversationId",
            "required": true,
            "in": "path",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "turnId",
            "required": true,
            "in": "path",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "Last-Event-ID",
            "in": "header",
            "required": false,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": ""
          }
        },
        "security": [
          {
            "visitor-session": []
          }
        ],
        "summary": "Resume or replay the event stream of a turn",
        "tags": [
          "Public: turns"
        ]
      }
    },
    "/v1/public/conversations/{conversationId}/turns/{turnId}/cancel": {
      "post": {
        "description": "The partial answer is kept as `stopped`; the stream ends with `finishReason: cancelled`.",
        "operationId": "PublicTurnsController_cancel",
        "parameters": [
          {
            "name": "conversationId",
            "required": true,
            "in": "path",
            "schema": {
              "type": "string"
            }
          },
          {
            "name": "turnId",
            "required": true,
            "in": "path",
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "202": {
            "description": ""
          }
        },
        "security": [
          {
            "visitor-session": []
          }
        ],
        "summary": "Stop generating",
        "tags": [
          "Public: turns"
        ]
      }
    },
    "/v1/public/assets/{token}": {
      "get": {
        "description": "URLs come from attachments and citation previews; they expire after a few minutes.",
        "operationId": "AssetsController_send",
        "parameters": [
