data: {"citations":[{"id":"297558c3-6284-49d9-a09b-3e982594c8d9","marker":1,"kind":"text","documentId":"dbb5dac1-71f4-4254-b691-2be229fca417","documentTitle":"Employee Handbook (final run)","page":1,"snippet":"Every full-time employee receives 24 working days of paid annual leave per calendar year. Up to 5 unused days may be carried over to the next year and must be used before 31 March.","bbox":{"x0":0.0952,"y0":0.1625,"x1":0.8625,"y1":0.1945},"hasPreview":false},{"id":"8cc26d34-d430-400a-8b0d-cdf8df92f9c6","marker":3,"kind":"text","documentId":"dbb5dac1-71f4-4254-b691-2be229fca417","documentTitle":"Employee Handbook (final run)","page":2,"snippet":"Business travel must be booked through the travel desk at least seven days in advance. Economy class is used for flights shorter than six hours; business class needs director approval. Receipts must be submitted within 30 days of the trip. Claims without receipts are not reimbur…","bbox":{"x0":0.0898,"y0":0.1086,"x1":0.8457,"y1":0.1953},"hasPreview":true},{"id":"a6f0374f-3427-4e88-91f6-308f4350191e","marker":4,"kind":"text","documentId":"750976bc-bf50-4bf6-a414-b33716d13dfb","documentTitle":"Employee Handbook","page":1,"snippet":"New employees serve a probation period of six months. During probation the notice period is two weeks; after confirmation it is one month.","bbox":{"x0":0.0952,"y0":0.3639,"x1":0.8337,"y1":0.3959},"hasPreview":false},{"id":"33871e46-e374-4999-8249-3534003e0d21","marker":5,"kind":"text","documentId":"750976bc-bf50-4bf6-a414-b33716d13dfb","documentTitle":"Employee Handbook","page":1,"snippet":"Employees may work remotely on Tuesdays and Thursdays. Fully remote arrangements need written approval from the department head and are reviewed every six months.","bbox":{"x0":0.0952,"y0":0.2296,"x1":0.8624,"y1":0.2617},"hasPreview":false},{"id":"9e66a721-751d-4a08-8a9d-77e68813ee4b","marker":6,"kind":"text","documentId":"dbb5dac1-71f4-4254-b691-2be229fca417","documentTitle":"Employee Handbook (final run)","page":2,"snippet":"| Expense | Daily limit (BDT) | Approval | | --- | --- | --- | | Hotel, Dhaka | 9,000 | Manager | | Hotel, outside Dhaka | 6,500 | Manager | | Meals | 2,500 | None | | International per diem | USD 60 | Director |","bbox":{"x0":0.0928,"y0":0.2367,"x1":0.8564,"y1":0.3906},"hasPreview":true},{"id":"8bb7f786-eebc-4972-8e15-5efe996f17e4","marker":8,"kind":"text","documentId":"dbb5dac1-71f4-4254-b691-2be229fca417","documentTitle":"Employee Handbook (final run)","page":1,"snippet":"The Dhaka office is open from 9:00 to 17:30, Sunday to Thursday. Core collaboration hours are 11:00 to 15:00, when everyone is expected to be reachable.","bbox":{"x0":0.0952,"y0":0.2968,"x1":0.8419,"y1":0.3288},"hasPreview":false}]}

